void handle_sas_tasks(void) {
    struct command *cmd;
    again:
    while ((cmd = get_next_command(work_q)) != NULL) {
        unsigned int flags;
        spin_lock_irqsave(&cmd->task_state_lock, flags);
        if (cmd->task_state & SAS_TASK_NEED_RESET) {
            spin_unlock_irqrestore(&cmd->task_state_lock, flags);
            if (cmd->task_state & SAS_TASK_AT_LU) {
                if (recover_lu(cmd)) {
                    finish_command(cmd);
                } else {
                    log_error("Failed to recover logical unit for command.");
                    clear_queues();
                    goto again;
                }
            } else if (cmd->task_state & SAS_TASK_I_T_RESET) {
                if (recover_i_t(cmd)) {
                    finish_command(cmd);
                } else {
                    log_error("Failed to recover I_T relationship for command.");
                    clear_queues();
                    goto again;
                }
            } else if (cmd->task_state & SAS_TASK_ABORTED) {
                abort_command(cmd);
            } else if (cmd->task_state & SAS_TASK_COMPLETED) {
                finish_command(cmd);
            } else {
                log_error("Unknown task state encountered.");
                clear_queues();
            }
        }
        spin_unlock_irqrestore(&cmd->task_state_lock, flags);
    }
}

void handle_sas_tasks_recovery(void) {
    struct command *cmd, *tmp;

    again:
    list_for_each_entry_safe(cmd, tmp, &work_q, list) {
        unsigned long flags;

        spin_lock_irqsave(&cmd->task_state_lock, flags);
        if (cmd->task_state == SAS_TASK_NEED_DEV_RESET) {
            spin_unlock_irqrestore(&cmd->task_state_lock, flags);

            if (recover_lu(cmd)) {
                cmd->task_state = SAS_TASK_COMPLETE;
            } else if (recover_i_t(cmd)) {
                cmd->task_state = SAS_TASK_COMPLETE;
            } else {
                printk(KERN_ERR "Failed to recover SAS device.\n");
                cmd->task_state = SAS_TASK_COMPLETE;
            }

            goto again;
        } else if (cmd->task_state == SAS_TASK_ABORTED) {
            finish_command(cmd);
            list_del(&cmd->list);
            kfree(cmd);
        } else if (cmd->task_state == SAS_TASK_AT_LU) {
            clear_queues(cmd);
            cmd->task_state = SAS_TASK_COMPLETE;
        }

        spin_unlock_irqrestore(&cmd->task_state_lock, flags);
    }
}

void handle_and_recover_sas_tasks(void) {
    struct command *cmd, *tmp;
    again:
    list_for_each_entry_safe(cmd, tmp, &work_q, list) {
        unsigned long flags;

        if (!cmd->requires_device_reset)
            continue;

        spin_lock_irqsave(&cmd->task_state_lock, flags);
        switch (cmd->task_state) {
        case CMD_COMPLETED:
            finish_command(cmd);
            break;
        case CMD_ABORTED:
            clear_queues(cmd);
            break;
        case CMD_AT_LU:
            if (!recover_logical_unit(cmd)) {
                log_error("Failed to recover logical unit for command %p", cmd);
                spin_unlock_irqrestore(&cmd->task_state_lock, flags);
                continue;
            }
            break;
        default:
            if (!recover_i_t_relationship(cmd)) {
                log_error("Failed to recover I_T relationship for command %p", cmd);
                spin_unlock_irqrestore(&cmd->task_state_lock, flags);
                continue;
            }
            break;
        }
        spin_unlock_irqrestore(&cmd->task_state_lock, flags);
    }

    if (recovery_attempts_remaining--) {
        goto again;
    } else {
        log_error("Device could not be recovered after multiple attempts");
    }
}

void handle_and_recover_sas_tasks(void) {
    struct command *cmd, *tmp;
    again:
    list_for_each_entry_safe(cmd, tmp, &work_q, list) {
        unsigned long flags;

        spin_lock_irqsave(&cmd->task_state_lock, flags);
        if (cmd->task_reset_needed) {
            int ret;

            switch (cmd->state) {
                case SAS_TASK_STATE_COMPLETED:
                case SAS_TASK_STATE_ABORTED:
                    finish_command(cmd);
                    break;
                case SAS_TASK_STATE_AT_LU:
                    ret = recover_lu(cmd);
                    if (ret != 0) {
                        log_error("Failed to recover LU for command %p", cmd);
                        clear_command_queue(cmd);
                    }
                    break;
                case SAS_TASK_STATE_AT_I_T:
                    ret = recover_i_t(cmd);
                    if (ret != 0) {
                        log_error("Failed to recover I_T for command %p", cmd);
                        clear_command_queue(cmd);
                    }
                    break;
                default:
                    log_error("Unknown task state for command %p", cmd);
                    break;
            }

            cmd->task_reset_needed = 0;
        }
        spin_unlock_irqrestore(&cmd->task_state_lock, flags);
    }

    /* Repeat the loop if needed */
    goto again;
}

void handle_and_recover_sas_tasks(void) {
    struct command *cmd;
    int recovery_needed = 0;

    while (1) {
        Again:
        cmd = get_next_command(work_q);
        if (!cmd)
            break;

        spin_lock_irq(&cmd->task_lock);

        if (cmd->reset_needed) {
            switch (cmd->state) {
                case CMD_COMPLETED:
                    finish_command(cmd);
                    break;
                case CMD_ABORTED:
                    clear_command(cmd);
                    break;
                case CMD_AT_LU:
                    if (recover_lu(cmd)) {
                        recovery_needed = 1;
                    } else if (recover_i_t(cmd)) {
                        recovery_needed = 1;
                    } else {
                        log_error("Failed to recover device.");
                        release_command(cmd);
                    }
                    break;
                default:
                    release_command(cmd);
                    break;
            }
        } else {
            release_command(cmd);
        }

        spin_unlock_irq(&cmd->task_lock);

        if (recovery_needed) {
            recovery_needed = 0;
            goto Again;
        }
    }
}
